sp_widget.client_script:
api.controller=function($scope) {
	/* widget controller */
	var c = this;

	c.activeTab = 'history';
};

sp_widget.css:
.headers-container{
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  align-items: center;
  justify-content: center;

  .active-header{
    border-bottom: .2rem solid #fff;
  }
}

.details-container{
  margin-top:20px;
  padding:0;
}

.tabs-container{
  padding:0;
}

.english{
  font-size:18px;
  font-weight:bold;
}

@media only screen and (max-width: 762px){
  .headers-container{
  	flex-direction: column;
    row-gap: 1.5rem;
  }
}

sp_widget.script:
(function() {
  /* populate the 'data' object */
  /* e.g., data.table = $sp.getValue('table'); */
data.ticketConversationWidget = $sp.getWidget('sw-ticket-conversations');
data.campaignArtifactsWidget = $sp.getWidget('star_wars_campaigns');
data.encountersWidget = $sp.getWidget('star_wars_encounter_builder');
data.isGM = checkGM();
data.rollHistoryLabel = 'Datapad';
data.campaignArtifactLabel = 'Campaign Artifacts';

	function checkGM(){
		var campaign = new GlideRecord('x_176383_star_wars_campaign');
		campaign.get($sp.getParameter('campaign'));
		return campaign.game_master == gs.getUserID() ? true : false;
	}
})();
